    },
    {
      "muscleGroup": "shoulders",
      "severity": "mild",
      "observation": "Shoulders accounted for just 5.2% of volume and 2 sets, the lowest of any muscle group tracked. While back training does involve the rear deltoids, direct shoulder work is minimal and worth monitoring."
    },
    {
      "muscleGroup": "legs",
      "severity": "mild",
      "observation": "Legs received 6 sets and 22.3% of volume, which is more reasonable, but the strength index remained flat at 103. Adding a small progression stimulus to leg work would be beneficial."
    }
  ],
  "deloadRecommended": false,
